import pandas as pd
import random
import re

def task_func(data_list, seed=None):
    operations = ['remove', 'replace', 'shuffle', 'randomize']
    if seed is not None:
        random.seed(seed)

    def process_string(s):
        substrings = [sub.strip() for sub in re.split(r'\s*,\s*', s)]
        operation = random.choice(operations)

        if operation == 'remove':
            if len(substrings) > 1:
                index = random.randint(0, len(substrings) - 1)
                substrings.pop(index)
        elif operation == 'replace':
            index = random.randint(0, len(substrings) - 1)
            substrings[index] = 'random_string'
        elif operation == 'shuffle':
            random.shuffle(substrings)
        elif operation == 'randomize':
            random.shuffle(substrings)

        modified_str = ', '.join(substrings)
        return s, modified_str

    if not data_list:
        return pd.DataFrame(columns=['Original String', 'Modified String'])

    original_strings, modified_strings = zip(*[process_string(s) for s in data_list])

    df = pd.DataFrame({
        'Original String': original_strings,
        'Modified String': modified_strings
    })

    return df
